def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Locate the solid separator, then copy the marker row/column nearest it
    # to the outside edge of its region.
    vertical=[]
    for c in range(1,w-1):
        vals=[g[r][c] for r in range(h)]
        if len(set(vals))==1 and vals[0]!=0:
            vertical.append(c)
    horizontal=[]
    for r in range(1,h-1):
        if len(set(g[r]))==1 and g[r][0]!=0:
            horizontal.append(r)
    if vertical and (not horizontal or len(vertical)>=len(horizontal)):
        c=vertical[len(vertical)//2]
        bg=g[0][0]
        candidates=[r for r in range(h) if sum(g[r][x]!=bg for x in range(c))>=1]
        src=max(candidates,key=lambda r:sum(g[r][x]!=bg for x in range(c)))
        for x in range(c):
            if g[src][x]!=bg:
                g[src][0]=g[src][x]
                g[src][x]=bg
    else:
        r=horizontal[len(horizontal)//2]
        bg=g[0][0]
        candidates=[c for c in range(w) if sum(g[y][c]!=bg for y in range(r))>=1]
        src=max(candidates,key=lambda c:sum(g[y][c]!=bg for y in range(r)))
        for y in range(r):
            if g[y][src]!=bg:
                g[0][src]=g[y][src]
                g[y][src]=bg
    return g

